/**
 * Leveled logging abstraction (docs/PLAN.md §2, decision D13).
 *
 * A thin wrapper instead of a dependency: console-only, never shipped
 * anywhere — remote log collection would contradict the privacy stance and
 * the strict CSP. Quiet by default in production; a user-accessible debug
 * flag (`?debug=1` query param or `localStorage["cta-debug"] = "1"`) elevates
 * verbosity for self-serve troubleshooting.
 *
 * SENSITIVE DATA RULE: never pass session-log-derived strings (titles, cwd,
 * git branches, prompts, file contents) or file bytes to a logger. Log
 * counts, enums, durations, and error codes only. Anything a user must act
 * on belongs in the UI, not the log.
 *
 * Works in both the main thread and Web Workers: environment probes are
 * guarded, and `setLogSink` lets worker code forward log events to the main
 * thread over the worker message protocol (wired in WP-07).
 */

export type LogLevel = 'debug' | 'info' | 'warn' | 'error' | 'silent'

const LEVEL_ORDER: Record<LogLevel, number> = {
  debug: 10,
  info: 20,
  warn: 30,
  error: 40,
  silent: 50,
}

export interface LogEvent {
  level: Exclude<LogLevel, 'silent'>
  scope: string
  args: unknown[]
}

export type LogSink = (event: LogEvent) => void

export interface Logger {
  debug: (...args: unknown[]) => void
  info: (...args: unknown[]) => void
  warn: (...args: unknown[]) => void
  error: (...args: unknown[]) => void
}

/** Pure level resolution, unit-testable without a browser environment. */
export function resolveInitialLevel(env: { debugFlag: boolean; isDev: boolean }): LogLevel {
  if (env.debugFlag) return 'debug'
  return env.isDev ? 'debug' : 'warn'
}

/** Probe the debug flag; every access is guarded so workers and restricted
 * contexts (no `localStorage`, no `location`) never throw. */
export function detectDebugFlag(): boolean {
  try {
    if (typeof location !== 'undefined' && typeof location.search === 'string') {
      if (new URLSearchParams(location.search).get('debug') === '1') return true
    }
  } catch {
    // ignore: no usable location in this context
  }
  try {
    if (typeof localStorage !== 'undefined' && localStorage.getItem('cta-debug') === '1') {
      return true
    }
  } catch {
    // ignore: storage unavailable (workers, blocked site data)
  }
  return false
}

const consoleSink: LogSink = (event) => {
  console[event.level](`[${event.scope}]`, ...event.args)
}

let currentLevel: LogLevel = resolveInitialLevel({
  debugFlag: detectDebugFlag(),
  isDev: typeof import.meta !== 'undefined' && Boolean(import.meta.env?.DEV),
})
let currentSink: LogSink = consoleSink

export function setLogLevel(level: LogLevel): void {
  currentLevel = level
}

export function getLogLevel(): LogLevel {
  return currentLevel
}

/** Replace the output target (e.g. a worker forwarding events to the main
 * thread). Pass `null` to restore the console sink. */
export function setLogSink(sink: LogSink | null): void {
  currentSink = sink ?? consoleSink
}

export function createLogger(scope: string): Logger {
  const emit = (level: Exclude<LogLevel, 'silent'>, args: unknown[]) => {
    if (LEVEL_ORDER[level] >= LEVEL_ORDER[currentLevel]) {
      currentSink({ level, scope, args })
    }
  }
  return {
    debug: (...args) => emit('debug', args),
    info: (...args) => emit('info', args),
    warn: (...args) => emit('warn', args),
    error: (...args) => emit('error', args),
  }
}

/**
 * WP-02 — the Web Worker message protocol (frozen with the contract).
 *
 * The main thread owns the Worker lifecycle. Cancellation has two layers:
 * a cooperative `cancel` message (the engine aborts via `AbortSignal` and
 * replies `cancelled`), and the host's `Worker.terminate()` as the hard
 * stop (always available; the UI's cancel button may use both).
 *
 * Worker log events are forwarded to the main thread as `log` messages so
 * the D13 logging abstraction covers worker code; the host replays them
 * into its own logger sink. Log args must obey the sensitive-data rule in
 * `src/lib/logger.ts`.
 */

import type { AnalysisResult, EngineProgress, ParseStats } from './contract'
import type { LogEvent, LogLevel } from '../lib/logger'
import type { PricingConfig } from './pricing'

/** Main thread -> worker. */
export type AnalysisWorkerRequest =
  | {
      type: 'start'
      /** `File` is structured-cloneable; the worker streams it (PLAN §2). */
      file: File
      pricing: PricingConfig
      /** Propagates the host's resolved log level into the worker. */
      logLevel: LogLevel
    }
  | { type: 'cancel' }

/** Worker -> main thread. */
export type AnalysisWorkerResponse =
  | { type: 'progress'; progress: EngineProgress }
  | { type: 'result'; result: AnalysisResult }
  | {
      type: 'rejected'
      verdict: 'not-a-session-log'
      stats: ParseStats
      /** Plain-language, translatable-key-friendly reason code. */
      reason: string
    }
  | { type: 'cancelled' }
  | {
      type: 'error'
      code: 'file-too-large' | 'read-failure' | 'internal'
      message: string
    }
  | { type: 'log'; event: LogEvent }

