      if (signal.aborted) throw new DOMException('aborted', 'AbortError')
      const outcome: EngineOutcome = {
        kind: 'analysis',
        result: makeStubResult(input.fileName, input.fileSizeBytes, input.pricing.pricesAsOf),
      }
      return outcome
    },
  }
}

